const rawDate = $('When Called by Agent').first()?.json?.date;

function parseDateToIso(input) {
  if (!input) return null;
  if (typeof input !== 'string') {
    if (input instanceof Date) {
      return DateTime.fromJSDate(input).setZone('America/Costa_Rica').toFormat('yyyy-MM-dd');
    }
    return null;
  }

  const trimmed = input.trim();

  // 1. Direct ISO match: YYYY-MM-DD
  const isoMatch = trimmed.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (isoMatch) {
    const dt = DateTime.fromObject({
      year: parseInt(isoMatch[1], 10),
      month: parseInt(isoMatch[2], 10),
      day: parseInt(isoMatch[3], 10)
    }, { zone: 'America/Costa_Rica' });
    if (dt.isValid) return dt.toFormat('yyyy-MM-dd');
  }

  // 2. Common text & slash date patterns
  const formats = [
    'yyyy/MM/dd',
    'MM/dd/yyyy',
    'M/d/yyyy',
    'dd/MM/yyyy',
    'd/M/yyyy',
    'yyyy-M-d',
    'MMMM d, yyyy',
    'MMMM d yyyy',
    'MMM d, yyyy',
    'MMM d yyyy',
    'd MMMM yyyy',
    'd MMM yyyy'
  ];

  for (const fmt of formats) {
    const dt = DateTime.fromFormat(trimmed, fmt, { zone: 'America/Costa_Rica' });
    if (dt.isValid) return dt.toFormat('yyyy-MM-dd');
  }

  // 3. Fallback: ISO / RFC parsing or JS Date parse
  const fromIso = DateTime.fromISO(trimmed, { zone: 'America/Costa_Rica' });
  if (fromIso.isValid) return fromIso.toFormat('yyyy-MM-dd');

  const jsParsed = new Date(trimmed);
  if (!isNaN(jsParsed.getTime())) {
    const dt = DateTime.fromJSDate(jsParsed).setZone('America/Costa_Rica');
    if (dt.isValid) return dt.toFormat('yyyy-MM-dd');
  }

  return null;
}

const isoDate = parseDateToIso(rawDate);

if (!isoDate) {
  return [{
    json: {
      isValid: false,
      available: false,
      checkDate: rawDate || null,
      reason: 'invalid_date',
      message: 'The date provided could not be understood. Please ask the user to confirm the exact date (e.g. "August 10, 2026" or "2026-08-10").'
    }
  }];
}

const todayIso = DateTime.now().setZone('America/Costa_Rica').toFormat('yyyy-MM-dd');

if (isoDate < todayIso) {
  return [{
    json: {
      isValid: false,
      available: false,
      checkDate: isoDate,
      reason: 'past_date',
      message: 'That date is in the past. Please ask the user for a future date.'
    }
  }];
}

return [{
  json: {
    isValid: true,
    checkDate: isoDate
  }
}];

// isValid is false — Normalize & Validate Date already built the correct
// error payload (invalid_date or past_date). Just pass it through as-is.
return [{ json: $input.first().json }];

const checkDate = $('Normalize & Validate Date').item.json.checkDate;
return [{
  json: {
    isValid: true,
    available: false,
    checkDate,
    reason: 'availability_check_failed',
    message: 'The availability check could not be completed right now due to a temporary system issue. Do not assume the date is available — ask the user to try again in a moment, or offer to check a different date.'
  }
}];

const checkDate = $('Normalize & Validate Date').item?.json?.checkDate || $('Normalize & Validate Date').first()?.json?.checkDate;
const response = $input.first()?.json || {};
const events = response.items || [];

function extractLine(desc, label) {
  const re = new RegExp(`${label}:\\s*(.+)`, 'i');
  const match = (desc || '').match(re);
  return match ? match[1].trim() : null;
}

// Ignore cancelled events and robustly identify boat charters
const boatEvents = events.filter(ev => {
  if (ev.status === 'cancelled') return false;
  const descMatch = (ev.description || '').match(/Type:\s*.*Boat.*/i);
  const sumMatch = (ev.summary || '').match(/Boat.*Charter|Charter.*Boat|\bBoat\b/i);
  return descMatch || sumMatch;
});

if (boatEvents.length > 0) {
  const conflicts = boatEvents.map(conflict => ({
    summary: conflict.summary,
    start: conflict.start?.dateTime || conflict.start?.date,
    pickup_time: extractLine(conflict.description, 'Pickup Time') || null
  }));

  return [{
    json: {
      isValid: true,
      available: false,
      checkDate,
      reason: 'boat_already_booked',
      message: `Boat charters are fully booked on ${checkDate}. Only one boat charter can be booked per day, and that day is already taken.`,
      conflicting_bookings: conflicts
    }
  }];
}

return [{
  json: {
    isValid: true,
    available: true,
    checkDate,
    reason: 'no_conflict',
    message: `No boat charter is booked on ${checkDate}. This date is available.`,
    otherToursThatDay: events.filter(e => e.status !== 'cancelled').length
  }
}];

